import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { WORKSPACE_ROOT } from '../env.js';

/**
 * Minimal local evidence store for I-06.
 *
 * The database stores object keys, never binaries; this adapter writes the
 * bytes outside the web root. Keys are generated by the issuance service and
 * must remain relative paths, so a caller cannot escape the configured root.
 *
 * This is deliberately the small pilot implementation. The fuller I-04 adapter
 * (authorised retrieval, orphan TTL cleanup, MIME sniffing) remains separate.
 */
export interface EvidenceStore {
  readonly root: string;
  put(objectKey: string, bytes: Buffer): Promise<void>;
  get(objectKey: string): Promise<Buffer>;
  remove(objectKey: string): Promise<void>;
}

export class EvidencePathError extends Error {
  constructor(objectKey: string) {
    super(`Evidence key is not a safe relative path: ${objectKey}`);
    this.name = 'EvidencePathError';
  }
}

function safePath(root: string, objectKey: string): string {
  if (
    objectKey.trim() === '' ||
    path.isAbsolute(objectKey) ||
    objectKey.split(/[\\/]/).includes('..')
  ) {
    throw new EvidencePathError(objectKey);
  }
  const resolved = path.resolve(root, objectKey);
  const relative = path.relative(root, resolved);
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new EvidencePathError(objectKey);
  }
  return resolved;
}

export function createLocalDiskEvidenceStore(
  root: string = process.env['EVIDENCE_ROOT'] ?? path.join(WORKSPACE_ROOT, 'var', 'evidence'),
): EvidenceStore {
  const configured = root.trim() === '' ? path.join(WORKSPACE_ROOT, 'var', 'evidence') : root;
  const resolvedRoot = path.isAbsolute(configured)
    ? path.resolve(configured)
    : path.resolve(WORKSPACE_ROOT, configured);
  return {
    root: resolvedRoot,
    async put(objectKey, bytes) {
      const destination = safePath(resolvedRoot, objectKey);
      const directory = path.dirname(destination);
      await mkdir(directory, { recursive: true });
      const temporary = path.join(directory, `.tmp-${randomUUID()}`);
      try {
        await writeFile(temporary, bytes, { flag: 'wx' });
        await rename(temporary, destination);
      } catch (error) {
        await rm(temporary, { force: true }).catch(() => undefined);
        throw error;
      }
    },
    async get(objectKey) {
      return readFile(safePath(resolvedRoot, objectKey));
    },
    async remove(objectKey) {
      const target = safePath(resolvedRoot, objectKey);
      await rm(target, { force: true });
    },
  };
}
